  const x:any={...p,clubId,clubName:p.clubName||club.name,country:p.country||club.country,contractYears:p.contractYears??(2+hashText(p.id||p.name)%4),desiredWage:p.desiredWage||Math.round((p.wage||wageFor(p))*1.1/10000)*10000,role:p.role||((p.ovr||65)>=78?"KEY":(p.ovr||65)>=72?"FIRST":"SQUAD"),transferListed:!!p.transferListed,ratingTotal:p.ratingTotal||0,avgRating:p.avgRating||0,scouted:owned?true:!!p.scouted};
