function normalizeState(x:any){
  if(!x||x.version!==5)return null;x.squad=(x.squad||[]).map((p:any)=>normalizePlayer(p,true));for(const bag of [x.rivalSquads,x.worldSquads])for(const k of Object.keys(bag||{}))bag[k]=(bag[k]||[]).map((p:any)=>normalizePlayer(p,false));x.offers=x.offers||[];x.transferHistory=x.transferHistory||[];x.negotiation=x.negotiation||null;x.marketCountry=x.marketCountry||"ALL";x.marketClub=x.marketClub||"ALL";x.worldCountry=x.worldCountry||"LEAGUE";x.activeWorldClub=x.activeWorldClub||"1";return x;
}
function read(){try{const current=normalizeState(JSON.parse(localStorage.getItem(KEY)||"null"));if(current)return current;const legacy=JSON.parse(localStorage.getItem(LEGACY_KEY)||"null");return legacy?migrateLegacy(legacy):null}catch{return null}}
